import * as cdk from 'aws-cdk-lib';
import * as sqs from 'aws-cdk-lib/aws-sqs';
import * as cloudwatch from 'aws-cdk-lib/aws-cloudwatch';
import * as sns from 'aws-cdk-lib/aws-sns';
import * as subscriptions from 'aws-cdk-lib/aws-sns-subscriptions';

const dlq = sqs.Queue.fromQueueArn(this, 'OrdersDLQ', dlqArn);
const topic = new sns.Topic(this, 'DlqAlerts');

new cloudwatch.Alarm(this, 'DlqDepthAlarm', {
  metric: dlq.metricApproximateNumberOfMessagesVisible(),
  threshold: 100,
  evaluationPeriods: 2,
  datapointsToAlarm: 2,
  comparisonOperator: cloudwatch.ComparisonOperator.GREATER_THAN_THRESHOLD,
  alarmDescription: 'DLQ has more than 100 unprocessed messages',
  actionsEnabled: true,
});

topic.addSubscription(new subscriptions.EmailSubscription('oncall@example.com'));
